python3 - <<'EOF'
import json, glob, importlib, sys, traceback
failures=0
for path in sorted(glob.glob('examples/*.json')):
    service = path.rsplit('/',1)[1][:-5]
    mod = importlib.import_module(f'clients.{service}')
    cases = json.load(open(path))
    for i, case in enumerate(cases):
        rec = case['record']; expected = case['result']
        try:
            got = mod.normalize(rec)
            outcome = {'ok': got}
        except ValueError as e:
            outcome = {'err': 'ValueError'}
        except Exception as e:
            outcome = {'err': type(e).__name__}
            print(service, i, 'UNEXPECTED', e)
        if outcome != expected:
            failures += 1
            print('MISMATCH', service, i)
            print(' expected', json.dumps(expected, ensure_ascii=False))
            print(' got     ', json.dumps(outcome, ensure_ascii=False))
    # input immutability
    for i, case in enumerate(cases):
        before = json.dumps(case['record'], sort_keys=True)
        try: mod.normalize(case['record'])
        except ValueError: pass
        if json.dumps(case['record'], sort_keys=True) != before:
            failures += 1
            print('MUTATED INPUT', service, i)
print('failures:', failures)
EOF

